// Nunca se reenvía la salida cruda del LLM al CRM: acá se valida contra los enums reales
// del Sheet y contra el catálogo de servicios, con fallbacks conservadores.
const raw = $input.first().json;
const ia = (raw && typeof raw.output === 'object' && raw.output !== null) ? raw.output : (raw || {});
const prev = $('CRM - Adjuntar catálogo de servicios').first().json;

const pick = (v, permitidos, fallback) => permitidos.includes(v) ? v : fallback;
const aBool = (v) => v === true || String(v).trim().toLowerCase() === 'true';

const intencion   = pick(ia.intencion,   ['Info precio', 'Agendar', 'Urgencia dolor', 'Reprogramar', 'Reclamo'], 'Info precio');
const sentimiento = pick(ia.sentimiento, ['Positivo', 'Neutro', 'Negativo'], 'Neutro');
const urgencia    = pick(ia.urgencia,    ['Alta', 'Media', 'Baja'], 'Media');

// Un reclamo es un caso de servicio, no una venta: no abre ni mueve oportunidades.
// OJO: el escalamiento a una persona NO se decide acá. Lo resuelve el workflow principal
// (¿Requiere Escalamiento? → aviso por correo). Por eso este flujo ya no clasifica ni
// escribe requiere_humano: dos LLM distintos decidiendo lo mismo terminan contradiciéndose.
const es_reclamo = intencion === 'Reclamo';

// servicio_interes debe existir en el catálogo real; si no, se descarta y se deja rastro en notas.
const ids = Array.isArray(prev.ids_validos) ? prev.ids_validos : [];
const servicio_ia = ia.servicio_interes ? String(ia.servicio_interes).trim() : '';
const servicio_valido = ids.includes(servicio_ia) ? servicio_ia : '';
const nota_servicio = (servicio_ia && !servicio_valido) ? `[IA sugirió "${servicio_ia}", sin match en catálogo] ` : '';

// Si ya existe una oportunidad abierta para este teléfono, ya se decidió antes que es un lead:
// no se le vuelve a preguntar a la IA en cada mensaje de la conversación.
const es_nuevo = prev.modo === 'evaluar_nuevo';
const es_lead = es_nuevo ? aBool(ia.es_lead) : true;

const notas = es_nuevo
  ? `${nota_servicio}Lead generado automáticamente desde WhatsApp. Primer mensaje: "${prev.mensaje_texto}"`
  : `${prev.notas_actuales ? prev.notas_actuales + '\n' : ''}[${prev.fecha_evento}] ${nota_servicio}${prev.mensaje_texto}`;

return [{ json: {
  es_lead,
  es_reclamo,
  modo: prev.modo,
  id_oportunidad: prev.id_oportunidad || '',
  id_paciente: prev.id_paciente || '',
  nombre_lead: prev.nombre_lead || '',
  telefono: prev.telefono || '',
  fecha_creacion: prev.fecha_creacion || prev.fecha_evento || '',
  canal_origen: prev.canal_origen || 'WhatsApp',
  servicio_interes: servicio_valido || prev.servicio_interes_actual || '',
  etapa: prev.etapa || 'Nuevo',
  valor_estimado: prev.valor_estimado === 0 ? 0 : (prev.valor_estimado || ''),
  intencion,
  sentimiento,
  urgencia,
  asignado_a: prev.asignado_a || 'Bot',
  fecha_seguimiento: prev.fecha_seguimiento || '',
  motivo_perdida: prev.motivo_perdida || '',
  notas,
  // Marca de última actividad: es lo que alimenta la regla de dormancia en la próxima corrida.
  fecha_ultima_interaccion: prev.fecha_evento || '',
  // Se arrastran para la fila de Interacciones que se escribe al final del flujo.
  mensaje_texto: prev.mensaje_texto || '',
  fecha_evento: prev.fecha_evento || '',
}}];

// Siguiente correlativo OPP-XXXX = max existente + 1.
// Limitación conocida y aceptada para este alcance de demo: si dos leads nuevos entraran
// de forma concurrente podrían leer el mismo máximo y colisionar.
const filas = $input.all().map(i => i.json).filter(r => r && r.id_oportunidad);
const nums = filas
  .map(r => parseInt(String(r.id_oportunidad).replace(/^OPP-/i, ''), 10))
  .filter(n => Number.isFinite(n));
const siguiente = (nums.length ? Math.max(...nums) : 0) + 1;

const prev = $('CRM - Validar salida de IA').first().json;
return [{ json: { ...prev, id_oportunidad: 'OPP-' + String(siguiente).padStart(4, '0') } }];

// Punto único de convergencia: acá llegan las tres salidas posibles del flujo
// (oportunidad guardada, mensaje descartado, reclamo) para dejar UNA fila en Interacciones.
// Esta pestaña es la que conserva el historial de intenciones: la fila de Oportunidades
// solo guarda el estado ACTUAL y sobrescribe intencion/sentimiento/urgencia en cada mensaje.
const base = $('CRM - Validar salida de IA').first().json;

// El id definitivo solo existe si esta corrida generó una oportunidad nueva.
let id_oportunidad = base.id_oportunidad || '';
try {
  const gen = $('CRM - Generar id_oportunidad').first().json;
  if (gen && gen.id_oportunidad) id_oportunidad = gen.id_oportunidad;
} catch (e) {
  // El nodo no corrió en esta rama: es un reclamo, un no-lead, o una oportunidad ya existente.
}

let accion;
if (base.es_reclamo) accion = 'reclamo';
else if (!base.es_lead) accion = 'descartado_no_lead';
else if (base.modo === 'evaluar_nuevo') accion = 'oportunidad_creada';
else accion = 'oportunidad_actualizada';

// id_interaccion sin leer la hoja: timestamp + sufijo aleatorio. Evita la lectura extra y
// la condición de carrera que sí arrastra el correlativo OPP-XXXX.
const stamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
const sufijo = Math.random().toString(36).slice(2, 6).toUpperCase();

return [{ json: {
  id_interaccion: `INT-${stamp}-${sufijo}`,
  id_oportunidad,
  telefono: base.telefono || '',
  fecha: base.fecha_evento || '',
  canal: base.canal_origen || 'WhatsApp',
  mensaje: base.mensaje_texto || '',
  intencion: base.intencion || '',
  sentimiento: base.sentimiento || '',
  urgencia: base.urgencia || '',
  accion,
}}];

// Chatwoot manda el telefono en E.164 pegado (+50679934925) pero el CRM lo guarda
// en formato costarricense con espacio y guion (+506 7993-4925). El filtro de
// Google Sheets es igualdad EXACTA: sin normalizar, ninguna busqueda haria match.
const lead = $input.first().json;
const crudo = String(lead.telefono || '').trim();
const digitos = crudo.replace(/\D/g, '');

let telefono = crudo;
if (digitos.length === 11 && digitos.startsWith('506')) {
  telefono = `(+506) ${digitos.slice(3, 7)}-${digitos.slice(7, 11)}`;
} else if (digitos.length === 8) {
  // por si llega sin codigo de pais
  telefono = `(+506) ${digitos.slice(0, 4)}-${digitos.slice(4, 8)}`;
}

return [{ json: { ...lead, telefono, telefono_crudo: crudo } }];

// Solo para pruebas: aplana el body del webhook al shape que
// entrega el Execute Workflow Trigger.
return [{ json: $input.first().json.body }];
